function box(id,p,size,color,{solid=true,tags=[],type='wall'}={}){const m=new THREE.Mesh(new THREE.BoxGeometry(...size),new THREE.MeshStandardMaterial({color,roughness:.8}));m.position.fromArray(p);scene.add(m);if(solid){const s={id,building:'lab',type,state:'intact',size:[...size],tags,body:{position:m.position,quaternion:m.quaternion},mesh:m};sections.push(s);}return m;}
