function dummy(id,p,yaw=0){const root=new THREE.Group();root.position.fromArray(p);root.rotation.y=yaw;scene.add(root);const mat=new THREE.MeshStandardMaterial({color:'#d28a51',roughness:.7});const torso=new THREE.Mesh(new THREE.BoxGeometry(1.4,1.7,.85),mat);torso.position.y=1.15;root.add(torso);const head=new THREE.Mesh(new THREE.BoxGeometry(.75,.65,.7),mat);head.position.y=2.3;root.add(head);const face=new THREE.Mesh(new THREE.BoxGeometry(.6,.15,.12),new THREE.MeshBasicMaterial({color:'#73ffcc'}));face.position.set(0,2.35,.4);root.add(face);const entity={root,recordHit:()=>{}},unit=damage.add(id,'robot',entity,config.lab.dummyHealth);unit.shapes=[{center:new THREE.Vector3(p[0],p[1]+1.3,p[2]),half:{x:.7,y:1.3,z:.55},rotation:root.quaternion.clone(),part:'dummy'}];dummies.push(unit);return unit;}
