const isHazard=p=>p.y<config.lab.hazardHeight&&hazards.some(h=>p.x>h.minX&&p.x<h.maxX&&p.z>h.minZ&&p.z<h.maxZ);
function event(text){$('lab-event').textContent=text;}
function place(lane='start'){const positions={start:config.lab.start,gap:[0,6.14,9],blocked:[-7,6.14,-24],untel:[25,6.14,18]},p=positions[lane];ninja.shuriken.reset();ninja.shurikenEffects.reset();ninja.attacks.reset();ninja.motion.reset();ninja.motion.body.reset({x:p[0],y:p[1],z:p[2]});ninja.yaw=lane==='untel'?-Math.PI/2:Math.PI;ninja.pitch=0;ninja.root.position.fromArray(p);ninja.pose(0,null);ninja.updateCamera(1,true);}
